const timeZone = 'Europe/Paris';
const parts = new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date());
const part = (name) => parts.find((value) => value.type === name).value;
const today = `${part('year')}-${part('month')}-${part('day')}`;
const addDays = (date, count) => { const value = new Date(`${date}T00:00:00Z`); value.setUTCDate(value.getUTCDate() + count); return value.toISOString().slice(0, 10); };
const offsetAt = (date) => {
  const value = new Intl.DateTimeFormat('en-US', { timeZone, timeZoneName: 'longOffset' }).formatToParts(date).find((item) => item.type === 'timeZoneName').value;
  const match = value.match(/^GMT(?:([+-])(\d{2}):(\d{2}))?$/);
  if (!match) throw new Error(`Fuseau horaire non reconnu : ${value}`);
  return match[1] ? (match[1] === '+' ? 1 : -1) * (Number(match[2]) * 60 + Number(match[3])) * 60000 : 0;
};
const midnight = (date) => {
  const [year, month, day] = date.split('-').map(Number);
  const target = Date.UTC(year, month - 1, day);
  let guess = target;
  for (let attempt = 0; attempt < 3; attempt += 1) {
    const next = target - offsetAt(new Date(guess));
    if (next === guess) break;
    guess = next;
  }
  return new Date(guess).toISOString();
};
const weekday = new Date(`${today}T00:00:00Z`).getUTCDay();
const daysUntilMonday = (8 - weekday) % 7;
const startDate = addDays(today, daysUntilMonday);
const endDate = addDays(startDate, 7);
return [{ json: { timeMin: midnight(startDate), timeMax: midnight(endDate), startDate, endDate: addDays(endDate, -1) } }];

const calendars = $json.items || [];
const find = (predicate, label) => {
  const matches = calendars.filter(predicate);
  if (matches.length !== 1) throw new Error(`Calendrier ${label} introuvable ou ambigu (${matches.length} résultat(s)).`);
  return matches[0];
};
const primary = find((calendar) => calendar.primary === true, 'principal');
const maud = find((calendar) => String(calendar.summary || '').toLocaleLowerCase().includes('maud'), 'Maud');
const shared = find((calendar) => String(calendar.summary || '').toLocaleLowerCase().includes('commun'), 'commun');
if (new Set([primary.id, maud.id, shared.id]).size !== 3) throw new Error('Les calendriers principal, Maud et commun doivent être distincts.');
const range = $('Préparer la semaine à venir').first().json;
return [primary, maud, shared].map((calendar) => ({ json: { calendar_id: calendar.id, calendar_name: calendar.summary || (calendar.primary ? 'Principal' : 'Sans nom'), timeMin: range.timeMin, timeMax: range.timeMax } }));

const events = $input.all().map((item) => item.json).filter((event) => event && event.start);
const range = $('Préparer la semaine à venir').first().json;
const formatDate = (date) => new Intl.DateTimeFormat('fr-FR', { timeZone: 'UTC', day: '2-digit', month: '2-digit', year: 'numeric' }).format(new Date(`${date}T12:00:00Z`));
const formatStart = (event) => event.start.date
  ? `${formatDate(event.start.date)} (journée entière)`
  : new Intl.DateTimeFormat('fr-FR', { timeZone: 'Europe/Paris', weekday: 'short', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }).format(new Date(event.start.dateTime));
const classify = (event) => {
  const normalize = (value) => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase();
  const title = normalize(event.summary);
  const calendar = normalize(event.calendar_name);
  if (event.eventType === 'birthday' || /\b(anniversaire|birthday)\b/.test(title)) return 'birthday';
  if (event.eventType === 'holiday' || /\b(fetes?|jours? feries?|holidays?)\b/.test(`${title} ${calendar}`)) return 'holiday';
  return 'event';
};
events.sort((left, right) => new Date(left.start.dateTime || `${left.start.date}T00:00:00Z`).getTime() - new Date(right.start.dateTime || `${right.start.date}T00:00:00Z`).getTime());
const lines = events.map((event) => {
  const location = event.location ? ` - ${event.location}` : '';
  const line = `${formatStart(event)} · ${event.calendar_name} · ${event.summary || '(sans titre)'}${location}`;
  const kind = classify(event);
  if (kind === 'birthday') return `🎂 _${line}_`;
  if (kind === 'holiday') return `🎉 _${line}_`;
  return `📌 *${line}*`;
});
const heading = `📅 *Agenda de la semaine du ${formatDate(range.startDate)} au ${formatDate(range.endDate)} :*`;
const text = `${heading}\n${lines.length ? lines.join('\n') : '📌 *Aucun événement prévu.*'}`;
return [{ json: { text } }];

const rows = $input.all().map((item) => item.json || {}).filter((row) => String(row.remoteJid || '').trim());
if (rows.length !== 1) throw new Error(`Groupe MyBot Home introuvable ou ambigu dans whatsapp_group_name (${rows.length} résultat(s)).`);
const recipient = String(rows[0].remoteJid).trim();
if (!recipient.endsWith('@g.us')) throw new Error('Le remoteJid de MyBot Home n’est pas un identifiant de groupe valide.');
const text = $('Préparer le message').first().json.text;
return [{ json: { recipient, text, delay: 0 } }];
